    # a separate path on each outgoing branch of a junction.
    paths: list[list[int]] = []

    def _out(node_id: int) -> list[int]:
        return sorted(
            out_sets.get(node_id, set()) & member_set
        )

    def _in(node_id: int) -> list[int]:
        return sorted(
            in_sets.get(node_id, set()) & member_set
        )

    starts = [
        node_id
        for node_id in members
        if len(_in(node_id)) == 0
    ]
    if len(members) == 1 and not _out(members[0]):
        paths.append([members[0]])
    else:
        def _walk(
            current: int,
            path: list[int],
            visited: set[tuple[int, int]],
        ) -> None:
            targets = _out(current)
            extended = False
            for target in targets:
                edge = (current, target)
                if edge in visited:
                    continue
                target_in = _in(target)
                if (
                    len(target_in) == 1
                    and len(targets) == 1
                ):
                    _walk(
                        target,
                        path + [target],
                        visited | {edge},
                    )
                    extended = True
                else:
                    paths.append(path + [target])
                    visited | {edge}
                    extended = True
            if not extended and path:
                if not paths or paths[-1] != path:
                    paths.append(path)

        for start in starts:
            _walk(start, [start], set())
        # Any edges missed by the entry-started walks (cycles
        # with no entry point) are covered from each of their
        # nodes.
        covered: set[tuple[int, int]] = set()
        for path in paths:
            for a, b in zip(path, path[1:]):
                covered.add((a, b))
        for node_id in members:
            for target in _out(node_id):
                if (node_id, target) in covered:
                    continue
                paths.append([node_id, target])
                covered.add((node_id, target))

    paths.sort()

