import json
import random

import air_quality.health as h


def brute_force(flow):
    def axis(axis):
        slices = axis["slices"]
        events = axis["events"]
        changes = axis["adjacency_changes"]

        nodes = []
        node_of = {}
        info = {}
        for si, runs in enumerate(slices):
            for ri, run in enumerate(runs):
                nid = len(nodes)
                node_of[(si, ri)] = nid
                first, last, region, state = run
                info[nid] = (si, ri, first, last, region)
                nodes.append([nid, si, ri, first, last, region, state])

        transitions = []
        edges = set()
        for pi, evs in enumerate(events):
            plist = []
            for kind, frm, to, overlap in evs:
                fn = sorted(node_of[(pi, r)] for r in frm)
                tn = sorted(node_of[(pi + 1, r)] for r in to)
                plist.append([kind, fn, tn, overlap])
                for s in fn:
                    for t in tn:
                        if info[s][4] != info[t][4]:
                            continue
                        if max(info[s][2], info[t][2]) > min(
                            info[s][3], info[t][3]
                        ):
                            continue
                        edges.add((s, t))
            transitions.append(plist)

        # undirected components
        parent = list(range(len(nodes)))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            parent[find(a)] = find(b)

        for s, t in edges:
            union(s, t)
        groups = {}
        for nid in range(len(nodes)):
            groups.setdefault(find(nid), []).append(nid)
        comps = sorted(groups.values(), key=lambda m: min(m))

        outd = {n: set() for n in range(len(nodes))}
        ind = {n: set() for n in range(len(nodes))}
        for s, t in edges:
            outd[s].add(t)
            ind[t].add(s)

        lineages = []
        comp_regions = []
        for cid, members in enumerate(comps):
            ms = set(members)
            entries = sorted(n for n in members if not (ind[n] & ms))
            exits = sorted(n for n in members if not (outd[n] & ms))

            paths = []
            if len(members) == 1 and not outd[members[0]] & ms:
                paths = [[members[0]]]
            else:
                for s in members:
                    ts = sorted(outd[s] & ms)
                    ins = sorted(ind[s] & ms)
                    if not ts:
                        continue
                    if len(ins) == 1 and len(ts) == 1:
                        continue
                    for t in ts:
                        p = [s, t]
                        cur = t
                        while True:
                            nx = sorted(outd[cur] & ms)
                            ni = sorted(ind[cur] & ms)
                            if len(ni) != 1 or len(nx) != 1:
                                break
                            cur = nx[0]
                            p.append(cur)
                        paths.append(p)
                # verify edge coverage
            comp_regions.append({info[n][4] for n in members})
            lineages.append([cid, sorted(members), entries, exits, paths, None])

        for cid, members in enumerate(comps):
            regions = comp_regions[cid]
            ch = []
            for rec in changes:
                earlier, later, added, removed = rec
                if not added and not removed:
                    continue
                hit = any(r in regions for e in added for r in e) or any(
                    r in regions for e in removed for r in e
                )
                if hit:
                    ch.append([earlier, later, added, removed])
            lineages[cid][5] = ch
            lineages[cid][4].sort()

        return {"nodes": nodes, "transitions": transitions, "lineages": lineages}

    return {
        "budgets": flow["budgets"],
        "z": flow["z"],
        "axes": {
            "budget": axis(flow["axes"]["budget"]),
            "z": axis(flow["axes"]["z"]),
        },
    }


def random_flow(rng, n_slices, max_runs, n_regions, max_idx):
    slices = []
    for _ in range(n_slices):
        n_runs = rng.randrange(1, max_runs + 1)
        runs = []
        pos = 0
        for r in range(n_runs):
            length = rng.randrange(1, max_idx // max(n_runs, 1) + 2)
            first = pos
            last = pos + length - 1
            pos = last + 1
            runs.append([first, last, rng.randrange(n_regions), rng.choice(
                [[None], [rng.randrange(3)], [1, [2, None]]
            )])
        slices.append(runs)

    events = []
    kinds = ["enter", "exit", "continue", "split", "merge", "merge_split"]
    for pi in range(n_slices - 1):
        evs = []
        # pick a few random components
        used_p, used_n = set(), set()
        for _ in range(rng.randrange(0, 4)):
            fp = [i for i in range(len(slices[pi])) if i not in used_p]
            tn = [i for i in range(len(slices[pi + 1])) if i not in used_n]
            if not fp and not tn:
                break
            frm = sorted(rng.sample(fp, rng.randrange(1, min(2, len(fp)) + 1))) if fp else []
            to = sorted(rng.sample(tn, rng.randrange(1, min(2, len(tn)) + 1))) if tn else []
            # occasionally make empty side
            if rng.random() < 0.15:
                frm = []
            if rng.random() < 0.15:
                to = []
            if not frm and not to:
                continue
            used_p.update(frm)
            used_n.update(to)
            overlap = []
            for fi in frm:
                for ti in to:
                    a, b, _, _ = slices[pi][fi]
                    c, d, _, _ = slices[pi + 1][ti]
